  "Ajusta automaticamente Offload (PPE/Flowtable), IRQ Balance, buffers TCP e limites de Conntrack sob medida para o processador e a memória deste roteador.": "Automatically tunes Offload (PPE/Flowtable), IRQ Balance, TCP buffers, and Conntrack limits tailored for this router's processor and memory.",
  "Blindagem de Modo Satélite": "Satellite Mode Shielding",
  "🛡️ O controle de Bufferbloat (SQM / CAKE) é exclusivo do Roteador Mestre.": "🛡️ Bufferbloat control (SQM / CAKE) is exclusive to the Master Router.",
  "🛡️ Speedify Gerenciado no Mestre": "🛡️ Speedify Managed on Master",
  "🛡️ Multi-WAN Gerenciado no Mestre": "🛡️ Multi-WAN Managed on Master",
  "🛡️ Exclusivo do Roteador Mestre (Gateway principal).": "🛡️ Exclusive to Master Router (Main Gateway).",
  "🛡️ O serviço Multi-WAN é exclusivo do Roteador Mestre.": "🛡️ Multi-WAN service is exclusive to the Master Router.",
  "🛡️ O serviço Speedify (Bonding de WANs) é exclusivo do Roteador Mestre.": "🛡️ Speedify service (WAN Bonding) is exclusive to the Master Router.",
  "O controle SQM / CAKE é exclusivo do Roteador Mestre e permanece desativado neste satélite.": "SQM / CAKE control is exclusive to the Master Router and remains disabled on this satellite.",
  "🛡️ Fila Exclusiva do Roteador Mestre": "🛡️ Master Router Exclusive Queue",
  "Modo Satélite / Ponto de Acesso": "Satellite / Access Point Mode",
  "Este roteador opera como nó Satélite / Ponto de Acesso em ponte transparente. O gerenciamento de tráfego de internet e filas SQM deve ser feito diretamente no roteador principal para evitar degradação de desempenho local.": "This router operates as a Satellite / Access Point node in transparent bridge mode. Internet traffic management and SQM queues must be configured on the main router to prevent local performance degradation.",
  "Nós Satélites e Pontos de Acesso operam em ponte transparente e não realizam balanceamento ou failover de conexões WAN. Configure o Multi-WAN diretamente no roteador principal.": "Satellite and Access Point nodes operate in transparent bridge mode and do not perform WAN load balancing or failover. Configure Multi-WAN on the primary router.",
  "Nós Satélites e Pontos de Acesso operam como pontes transparentes na rede local. A agregação de links de internet (Speedify Bonding) deve rodar diretamente no roteador de borda principal (Gateway).": "Satellite and Access Point nodes operate as transparent local bridges. Internet link bonding (Speedify Bonding) must run directly on the main gateway router.",
  "Este nó opera como extensor em ponte transparente. O tráfego de saída, Multi-WAN e controle de Bufferbloat (SQM) são centralizados no Roteador Mestre.": "This node operates as a transparent bridge extender. Outbound traffic, Multi-WAN, and Bufferbloat control (SQM) are centralized on the Master Router.",
  "O controle de Bufferbloat (SQM / CAKE) atua exclusivamente na porta de internet (WAN) do Roteador Mestre (Gateway). Em nós satélites, todo o tráfego passa em ponte direta (L2) para não limitar nem degradar a velocidade local do Wi-Fi.": "Bufferbloat control (SQM / CAKE) operates exclusively on the Master Router (Gateway) WAN port. On satellite nodes, all traffic flows over direct L2 bridge to avoid limiting or degrading local Wi-Fi speeds.",
  "O balanceamento e failover de conexões de internet pertencem ao Roteador Mestre (Gateway). Em nós satélites, todo o tráfego é encaminhado diretamente via enlace local.": "Internet connection load balancing and failover belong to the Master Router (Gateway). On satellite nodes, all traffic is forwarded directly via local link.",
  "A agregação de links de internet (Speedify Bonding) atua nas portas WAN do Roteador Mestre (Gateway). Nós satélites mantêm tráfego local transparente.": "Internet link bonding (Speedify Bonding) operates on the Master Router (Gateway) WAN ports. Satellite nodes maintain transparent local traffic.",
  "Desativado e gerenciado centralmente pelo Roteador Mestre": "Disabled and centrally managed by Master Router",
  "MESTRE GERENCIA": "MASTER MANAGED",
  "GERENCIADO PELO MESTRE": "MANAGED BY MASTER",
  "INATIVO NO SATÉLITE": "INACTIVE ON SATELLITE",
